    log = REPO / "backups" / ".live" / "BACKUP_LOG.md"
    log = log if log.exists() else REPO / "backups" / "BACKUP_LOG.md"
    times = []
    for row in log.read_text().splitlines() if log.exists() else []:
        m = re.match(r"\| (\d{4}-\d\d-\d\dT[\d:]+\+00:00) \|", row)
        if m:
